// <auto-generated/>
using System.Configuration;
using System.Threading;
using Fanex.Caching;
using RemotingRef;

public static class CacheRef
{
    private static ICache velocityCache = CacheService.CreateInstance(CacheType.MemoryCache);

    private static string TWLang(string lang)
    {
        switch (lang)
        {
            case "en-US": return "en";
            case "zh-TW": return "ch"; // Traditional
            case "zh-CN": return "cs"; // Simplified
            case "ja-JP": return "jp";
            case "th-TH": return "th"; // Thai
            case "ko-KR": return "ko";
            default: return "en";
        }
    }

    private static bool IsWebService
    {
        get
        {
            return "1".Equals(ConfigurationManager.AppSettings["UseLiveDb"]);
        }
    }

    private static string Invoke(string functionName, object[] parameters)
    {
        int length = (parameters == null) ? 0 : parameters.Length;
        string[] ps = new string[length + 2];
        if (length > 0)
        {
            parameters.CopyTo(ps, 0);
        }

        ps[length] = functionName;
        ps[length + 1] = Thread.CurrentThread.CurrentCulture.Name;

        string key = string.Join("|", ps);
        string value = velocityCache.Get<string>(key);

        if (string.IsNullOrEmpty(value))
        {
            /*LiveDataService service = new LiveDataService();
            value = service.InvokeRemoteRef(functionName, parameters);
            velocityCache.Set<string>(key, value);*/
        }

        return value;
    }

    public static string GetBettype(object bettypeID)
    {
        return RefData.GetBetTypeName(bettypeID.ToString(), TWLang(Sunplus.Agent.Model.Entities.UserSession.Current.Language), string.Empty);
    }

    public static string GetBettype(object bettypeId, object betID)
    {
        // resourceId remove first character
        string resourceId = string.Empty;
        if (betID != null && betID.ToString().Length > 1)
        {
            resourceId = betID.ToString().Substring(1);
        }

        if (IsWebService)
        {
            return Invoke("GetBetTypeName", new object[] { bettypeId.ToString(), TWLang(Sunplus.Agent.Model.Entities.UserSession.Current.Language), string.Empty, resourceId });
        }

        return RefData.GetBetTypeName(bettypeId.ToString(), TWLang(Sunplus.Agent.Model.Entities.UserSession.Current.Language), string.Empty, resourceId);
    }

    public static string GetSportName(object sportID)
    {
        return RefData.GetSportName(sportID.ToString(), TWLang(Sunplus.Agent.Model.Entities.UserSession.Current.Language), string.Empty);
    }

    public static string GetTeamName(object teamID)
    {
        return RefData.GetTeamName(teamID.ToString(), TWLang(Sunplus.Agent.Model.Entities.UserSession.Current.Language), string.Empty);
    }

    public static string GetLeagueName(object leagueID)
    {
        return RefData.GetLeagueName(leagueID.ToString(), TWLang(Sunplus.Agent.Model.Entities.UserSession.Current.Language), string.Empty);
    }

    public static string GetFncIndexName(object indexId)
    {
        return RefData.GetFncIndexName(indexId.ToString(), TWLang(Sunplus.Agent.Model.Entities.UserSession.Current.Language));
    }

    public static string GetHorseTeamName(object codeId)
    {
        return RefData.GetHorseTeamName(codeId.ToString(), TWLang(Sunplus.Agent.Model.Entities.UserSession.Current.Language));
    }

    public static string GetOddsTypeName(object oddsTypeId)
    {
        return RefData.GetOddsTypeName(oddsTypeId.ToString(), TWLang(Sunplus.Agent.Model.Entities.UserSession.Current.Language));
    }

    public static string GetTWLang(string key)
    {
        return TWLang(key);
    }
}
